## Submitted testbench
```systemverilog
module tb;

  // ------------------------------------------------------------
  // Clock generation
  // ------------------------------------------------------------
  logic clk = 0;
  initial begin
    forever #(4) clk = ~clk;   // ~100 MHz clock
  end

  // ------------------------------------------------------------
  // DUT ports (named identically to the DUT for implicit binding)
  // ------------------------------------------------------------
  logic rst;
  logic [15:0] prescale;
  logic rxd;
  logic txd;
  logic s_axis_tvalid;
  logic s_axis_tready;
  logic [7:0] s_axis_tdata;
  logic tx_busy;
  logic rx_busy;
  logic rx_overrun_error;
  logic rx_frame_error;
  logic [7:0] m_axis_tdata;
  logic m_axis_tvalid;
  logic m_axis_tready;
  logic busy;          // internal busy signal
  logic overrun_error;
  logic frame_error;

  // ------------------------------------------------------------
  // Initialization of all ports
  // ------------------------------------------------------------
  initial begin
    rst            = 1'b0;
    prescale       = 16'h5;   // default prescale value
    rxd            = 1'b1;
    txd            = 1'b1;
    s_axis_tvalid  = 1'b0;
    s_axis_tready  = 1'b0;
    s_axis_tdata   = 8'h00;
    tx_busy        = 1'b0;
    rx_busy        = 1'b0;
    rx_overrun_error = 1'b0;
    rx_frame_error   = 1'b0;
    busy           = 1'b0;
    overrun_error  = 1'b0;
    frame_error    = 1'b0;
  end

  // ------------------------------------------------------------
  // Helper tasks
  // ------------------------------------------------------------
  // Wait a given number of clock cycles (negative edge triggered)
  task automatic wait_clks(input int n);
    repeat (n) @(negedge clk);
  endtask

  // Compute bit‑clocks from the preset prescale value
  localparam int BIT_CLOCKS = 8 * 16'd5;   // 5·8 = 40 clock cycles per bit

  // Send one byte on the UART receive line (LSB‑first, 8N1)
  task automatic uart_send_byte(input byte unsigned b);
    // start bit
    rxd = 1'b0;
    wait_clks(BIT_CLOCKS);
    // 8 data bits
    for (int i = 0; i < 8; i++) begin
      rxd = b[i];
      wait_clks(BIT_CLOCKS);
    end
    // stop bit
    rxd = 1'b1;
    wait_clks(BIT_CLOCKS);
  endtask

  // Simple reset sequence
  task automatic do_reset();
    rst = 1'b0;
    wait_clks(2);
    rst = 1'b1;
    wait_clks(2);
    rst = 1'b0;
    wait_clks(2);
  endtask

  // ------------------------------------------------------------
  // DUT instantiation (default parameters)
  // ------------------------------------------------------------
  uart dut (
    .clk               (clk),
    .rst               (rst),
    .s_axis_tdata      (s_axis_tdata),
    .s_axis_tvalid     (s_axis_tvalid),
    .s_axis_tready     (s_axis_tready),
    .txd               (txd),
    .rxd               (rxd),
    .tx_busy           (tx_busy),
    .rx_busy           (rx_busy),
    .rx_overrun_error  (rx_overrun_error),
    .rx_frame_error    (rx_frame_error),
    .prescale          (prescale),
    .m_axis_tdata      (m_axis_tdata),
    .m_axis_tvalid     (m_axis_tvalid),
    .m_axis_tready     (m_axis_tready)
  );

  // ------------------------------------------------------------
  // Main stimulus
  // ------------------------------------------------------------
  initial begin
    // Apply reset
    do_reset();

    // Wait a few cycles after reset
    wait_clks(10);

    // --------------------------------------------------------
    // 1) Send first frame (payload = 8'h3C)
    // --------------------------------------------------------
    uart_send_byte(8'h3C);

    // Allow time for the frame to be processed and the pending word
    // to be presented on m_axis_tdata/m_axis_tvalid
    wait_clks(600);

    // --------------------------------------------------------
    // 2) Send second frame (payload = 8'hA5) – this will be the
    //    word that appears while the first word is still pending
    // --------------------------------------------------------
    uart_send_byte(8'hA5);

    // Wait for the second frame to finish its internal processing
    wait_clks(600);

    // --------------------------------------------------------
    // 3) Accept the pending word (8'h3C) by asserting m_axis_tready
    //    on the exact clock where the new word (8'hA5) is already
    //    valid.  This satisfies the R12 coverage point:
    //       q_valid && q_ready && (q_data == 8'h3C) &&
    //       m_axis_tvalid && (m_axis_tdata == 8'hA5)
    // --------------------------------------------------------
    m_axis_tready = 1'b1;          // drive readiness high
    @(posedge clk);
    m_axis_tready = 1'b0;          // de‑assert after one cycle

    // Give the design a little extra time before finishing
    wait_clks(200);

    // End simulation – $finish guarantees clean exit
    $finish;
  end

endmodule
```

